void main() {
  runApp(const MaterialApp(home: Scaffold(body: ScatterSquaresPage())));
}

class ScatterSquaresPage extends StatelessWidget {
  const ScatterSquaresPage({super.key});

  @override
  Widget build(BuildContext context) {
    return Center(
      child: Container(
        width: 340,
        height: 340,
        decoration: BoxDecoration(borderRadius: BorderRadius.circular(24)),
        child: const Padding(padding: EdgeInsets.all(16), child: NestedScatterGrid()),
      ),
    );
  }
}

class NestedScatterGrid extends StatelessWidget {
  const NestedScatterGrid({super.key});

  @override
  Widget build(BuildContext context) {
    final random = Random(1);
    final placed = <Rect>[];

    final children = <Widget>[];

    for (var i = 0; i < 12; i++) {
      final size = random.nextDouble() * 60 + 40;

      Rect? rect;

      for (var attempt = 0; attempt < 100; attempt++) {
        final left = random.nextDouble() * (308 - size);
        final top = random.nextDouble() * (308 - size);

        final candidate = Rect.fromLTWH(left, top, size, size);

        final overlaps = placed.any((r) => r.overlaps(candidate));

        if (!overlaps) {
          rect = candidate;
          placed.add(candidate);
          break;
        }
      }

      if (rect == null) continue;

      children.add(
        Positioned(
          left: rect.left,
          top: rect.top,
          child: ScatterSquare(size: rect.width, seed: i * 100),
        ),
      );
    }

    return Stack(children: children);
  }
}

class ScatterSquare extends StatelessWidget {
  final double size;
  final int seed;

  const ScatterSquare({required this.size, required this.seed, super.key});

  @override
  Widget build(BuildContext context) {
    final random = Random(seed);

    final innerRects = <Rect>[];
    final innerChildren = <Widget>[];

    for (var i = 0; i < 8; i++) {
      final childSize = random.nextDouble() * (size * 0.22) + 6;

      Rect? rect;

      for (var attempt = 0; attempt < 80; attempt++) {
        final left = random.nextDouble() * (size - childSize);

        final top = random.nextDouble() * (size - childSize);

        final candidate = Rect.fromLTWH(left, top, childSize, childSize);

        final overlaps = innerRects.any((r) => r.overlaps(candidate));

        if (!overlaps) {
          rect = candidate;
          innerRects.add(candidate);
          break;
        }
      }

      if (rect == null) continue;

      innerChildren.add(
        Positioned(
          left: rect.left,
          top: rect.top,
          child: Container(
            width: rect.width,
            height: rect.height,
            decoration: BoxDecoration(
              color: Colors.primaries[random.nextInt(Colors.primaries.length)].withValues(alpha: 0.8),
              borderRadius: BorderRadius.circular(4),
            ),
          ),
        ),
      );
    }

    return Container(
      width: size,
      height: size,
      decoration: BoxDecoration(
        color: Colors.black.withValues(alpha: 0.03),
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: Colors.black.withValues(alpha: 0.06)),
      ),
      child: Stack(children: innerChildren),
    );
  }
}
